Write a test function named testWelcomeName that creates a fake event object with namedValues for "First Name" (Test) and "Last Name" (Member), and passes it to this function:

function logWelcome(e) {
  const answers = e.namedValues
  console.log(`Welcome, ${answers["First Name"][0]} ${answers["Last Name"][0]}!`)
}

key:
function testWelcomeName() {
  const fakeEvent = {
    namedValues: {
      "First Name": ["Test"],
      "Last Name": ["Member"]
    }
  }
  logWelcome(fakeEvent)
}

function logWelcome(e) {
  const answers = e.namedValues
  console.log(`Welcome, ${answers["First Name"][0]} ${answers["Last Name"][0]}!`)
}
